1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	
6	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
7	
8	/**
9	 * Single home for owner telephone normalization. Both the create pipeline's
10	 * {@link BuildOwner} (which stores the canonical form) and
11	 * {@link OwnerIdentity} (whose identity key detects duplicates) go through here, so the
12	 * stored form and the duplicate-comparison stay defined in one place.
13	 */
14	final class TelephoneNormalizer {
15	
16	    private TelephoneNormalizer() {
17	    }
18	
19	    /** Default country code assumed when the supplied number carries no explicit '+'. */
20	    private static final String DEFAULT_COUNTRY_CODE = "61";
21	
22	    /**
23	     * Required national-number length per country code. Insertion order is longest code
24	     * first so prefix matching resolves the most specific country. A code not listed here
25	     * is not length-checked beyond the generic 8-to-15 digit rule.
26	     */
27	    private static final Map<String, Integer> NATIONAL_LENGTHS = new LinkedHashMap<>();
28	
29	    static {
30	        NATIONAL_LENGTHS.put("61", 9); // Australia: +61 needs 9 national digits
31	        NATIONAL_LENGTHS.put("1", 10); // NANP: +1 needs 10 national digits
32	    }
33	
34	    /**
35	     * Canonical E.164 form to store for a supplied telephone. Spaces, dashes and brackets
36	     * are stripped. A leading '+' with its country code is kept; otherwise country code
37	     * '+61' is assumed and a single leading '0' is dropped from the national digits. The
38	     * result must have 8 to 15 digits after the '+', and — for a recognised country code —
39	     * the national number must match that country's required length ('+61' => 9 national
40	     * digits, '+1' => 10); otherwise the request is rejected with a 400. So
41	     * '0412 345 678' becomes '+61412345678'.
42	     */
43	    static String normalize(String telephone) throws InvalidTelephoneException {
44	        String e164 = toE164(telephone);
45	        if (e164 == null) {
46	            throw new InvalidTelephoneException(telephone);
47	        }
48	        return e164;
49	    }
50	
51	    /**
52	     * Comparison key used to detect duplicate telephones — the E.164 form. Lenient (never
53	     * throws) so whatever is already stored on existing owners still compares; when a value
54	     * cannot form valid E.164 it falls back to its stripped characters.
55	     */
56	    static String comparisonKey(String telephone) {
57	        String e164 = toE164(telephone);
58	        return e164 != null ? e164 : stripSeparators(telephone);
59	    }
60	
61	    /**
62	     * Produce the E.164 string for a telephone, or {@code null} when it cannot form a valid
63	     * one (non-digit content remaining, not 8 to 15 digits after the '+', or a national
64	     * number of the wrong length for its recognised country code).
65	     */
66	    private static String toE164(String telephone) {
67	        String cleaned = stripSeparators(telephone);
68	        String digits;
69	        if (cleaned.startsWith("+")) {
70	            digits = cleaned.substring(1);
71	        }
72	        else {
73	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
74	            digits = DEFAULT_COUNTRY_CODE + national;
75	        }
76	        if (!digits.matches("\\d{8,15}")) {
77	            return null;
78	        }
79	        if (!hasValidNationalLength(digits)) {
80	            return null;
81	        }
82	        return "+" + digits;
83	    }
84	
85	    /**
86	     * For a recognised country code, the national number (digits after the code) must have
87	     * exactly the length that country requires. Country codes not listed in
88	     * {@link #NATIONAL_LENGTHS} are accepted on the generic 8-to-15 digit rule alone.
89	     */
90	    /**
91	     * Split E.164 digits (the part after the '+') into {@code { countryCode, nationalNumber }}
92	     * using the recognised country codes (iterated longest/most-specific first, so '+61' wins
93	     * over '+1'). When no known code matches, assumes a two-digit country code — enough to still
94	     * render a '+CC national' display. Used by {@link TelephoneDisplay} to format for humans.
95	     */
96	    static String[] splitCountryCode(String digits) {
97	        for (String countryCode : NATIONAL_LENGTHS.keySet()) {
98	            if (digits.startsWith(countryCode)) {
99	                return new String[] { countryCode, digits.substring(countryCode.length()) };
100	            }
101	        }
102	        int codeLength = Math.min(2, digits.length());
103	        return new String[] { digits.substring(0, codeLength), digits.substring(codeLength) };
104	    }
105	
106	    private static boolean hasValidNationalLength(String digits) {
107	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTHS.entrySet()) {
108	            String countryCode = entry.getKey();
109	            if (digits.startsWith(countryCode)) {
110	                int nationalLength = digits.length() - countryCode.length();
111	                return nationalLength == entry.getValue();
112	            }
113	        }
114	        return true;
115	    }
116	
117	    private static String stripSeparators(String telephone) {
118	        return telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
119	    }
120	}
